-- SAP migration 006
-- Registered student devices and their verification credentials.

CREATE TABLE student_devices (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    student_id BIGINT NOT NULL,

    -- A student has slot 1 and slot 2 only
    device_slot SMALLINT NOT NULL,

    device_name VARCHAR(100) NOT NULL,

    -- Generated by the backend during device registration
    credential_id UUID NOT NULL UNIQUE,

    -- The device's public verification key will be stored here later
    device_public_key TEXT,

    status VARCHAR(20) NOT NULL DEFAULT 'pending',

    registered_at TIMESTAMPTZ,
    last_used_at TIMESTAMPTZ,
    revoked_at TIMESTAMPTZ,

    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT student_devices_student_fk
        FOREIGN KEY (student_id)
        REFERENCES students(user_id)
        ON DELETE CASCADE,

    CONSTRAINT student_devices_slot_check
        CHECK (device_slot IN (1, 2)),

    CONSTRAINT student_devices_status_check
        CHECK (status IN ('pending', 'active', 'revoked')),

    -- Active devices must have completed registration
    CONSTRAINT student_devices_active_key_check
        CHECK (
            status <> 'active'
            OR (
                device_public_key IS NOT NULL
                AND registered_at IS NOT NULL
            )
        )
);

-- Prevent two current registrations from occupying the same slot.
-- Revoked device history can remain in the table.
CREATE UNIQUE INDEX student_devices_current_slot_unique
    ON student_devices(student_id, device_slot)
    WHERE status IN ('pending', 'active');

CREATE INDEX student_devices_student_idx
    ON student_devices(student_id);

CREATE INDEX student_devices_status_idx
    ON student_devices(status);